exports.handler = async (event) => {
  // event 객체에 트리거된 이벤트 정보가 담겨 있다
  const message = event.Records
    ? event.Records[0].body
    : JSON.stringify(event);

  console.log('received:', message);

  return {
    statusCode: 200,
    body: JSON.stringify({ processed: true }),
  };
};
